import React, { useState, useEffect, useRef, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { categories as defaultCategories } from '../mocks/products';
import { useUI } from '../context/UIContext';
import { glassPanelClass, goldGlow, goldButtonClass, commonShadow } from '../utils/uiEffects';


const MenuFab = ({
  categories = defaultCategories,
  selectedCategory,
  onSelect,
  position = 'left'
}) => {
  const [open, setOpen] = useState(false);
  const { setMenuOpen } = useUI();

  const fabRef = useRef(null);
  const panelRef = useRef(null);

  useEffect(() => {
    setMenuOpen(open);
  }, [open, setMenuOpen]);

  // close on outside click or Escape — no visual backdrop (no page darkening)
  useEffect(() => {
    if (!open) return;
    const onPointerDown = (e) => {
      const target = e.target;
      if (!target) return;
      if (panelRef.current?.contains(target) || fabRef.current?.contains(target)) return;
      setOpen(false);
    };
    const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };

    document.addEventListener('pointerdown', onPointerDown);
    document.addEventListener('keydown', onKey);

    // focus first interactive item in panel for keyboard users
    const timer = setTimeout(() => {
      const btn = panelRef.current?.querySelector('button');
      btn?.focus?.();
    }, 0);

    return () => {
      clearTimeout(timer);
      document.removeEventListener('pointerdown', onPointerDown);
      document.removeEventListener('keydown', onKey);
      // return focus to FAB when closing
      fabRef.current?.focus?.();
    };
  }, [open]);

  const handleSelect = useCallback((id) => {
    onSelect(id);
    // Keep the menu open as requested by user
    // setOpen(false);
  }, [onSelect]);

  return (

    <div className={`fixed bottom-8 ${position === 'left' ? 'left-8' : 'right-8'} z-[150]`}>
      <div className="relative">
        {/* Panel (Solid background, no blur) */}
        <AnimatePresence>
          {open && (
            <motion.div
              ref={panelRef}
              role="menu"
              aria-label="Menu categories"
              initial={{ y: 12, opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              exit={{ y: 12, opacity: 0 }}
              transition={{ type: 'spring', stiffness: 320, damping: 26 }}
              className={`bg-[#1A110D] rounded-xl border border-gold/20 p-4 ${commonShadow} w-56 absolute bottom-full mb-4 right-0 max-h-[48vh] overflow-hidden z-50`}
              style={{ backdropFilter: 'none', WebkitBackdropFilter: 'none' }}
            >
              <div className="flex items-center justify-between mb-3">
                <h4 className="font-syncopate text-sm text-cream">Menu</h4>
                <button
                  aria-label="Close menu"
                  className="text-cream/60 hover:text-gold transition-colors cursor-pointer p-1"
                  onClick={() => setOpen(false)}
                >
                  <i className="ri-close-line text-lg" />
                </button>
              </div>

              <div
                className="flex flex-col gap-2 overflow-y-auto pr-1 custom-scrollbar"
                style={{
                  maxHeight: 'calc(48vh - 56px)',
                  overscrollBehavior: 'contain',
                  WebkitOverflowScrolling: 'touch'
                }}
              >
                {categories.map((cat) => (
                  <button
                    key={cat.id}
                    onClick={() => handleSelect(cat.id)}
                    className={`flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm transition-all text-left border ${selectedCategory === cat.id
                      ? 'bg-gradient-to-r from-gold to-gold-light text-obsidian font-bold border-transparent shadow-lg'
                      : 'bg-[#25160F] text-cream/70 border-gold/10 hover:border-gold/30 hover:bg-[#2A1D16]'
                      }`}
                  >
                    <i className={`${cat.icon} text-lg ${selectedCategory === cat.id ? 'text-obsidian' : 'text-gold/80'}`} />
                    <span className="font-outfit">{cat.name}</span>
                  </button>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Floating Menu Button */}
        <motion.button
          ref={fabRef}
          initial={{ y: 40, opacity: 0, scale: 0.95 }}
          animate={{ y: 0, opacity: 1, scale: 1 }}
          whileTap={{ scale: 0.96 }}
          whileHover={{ y: -6 }}
          onClick={() => setOpen((v) => !v)}
          aria-expanded={open}
          aria-haspopup="menu"
          aria-label="Open menu categories"
          className="group relative menu-fab-large"
        >
          <div className={`${goldGlow} group-hover:opacity-40`} />

          <div className={`fab-inner relative flex items-center gap-3 px-5 py-3 rounded-2xl ${goldButtonClass} ${commonShadow}`}>
            <i className="ri-restaurant-line text-2xl text-obsidian" />
            <span className="font-outfit text-base text-obsidian font-medium">Menu</span>
          </div>
        </motion.button>
      </div>
    </div>
  );
};

export default React.memo(MenuFab);
