import { useState, useEffect, useMemo, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useParams } from 'react-router-dom';
import ProductQuickView from '../../components/ProductQuickView';
import { products, categories } from '../../mocks/products';
import { stores } from '../../mocks/stores';
import ResponsiveImage from '../../components/ResponsiveImage';
import MenuFab from '../../components/MenuFab';
import ProductCard from '../../components/ProductCard';
import MenuStickySearch from '../../components/MenuStickySearch';

export default function Menu() {
  const { storeId } = useParams();
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [query, setQuery] = useState('');
  const currentStore = stores.find(s => s.id === storeId);

  const [selectedProduct, setSelectedProduct] = useState(null);
  const [isQuickViewOpen, setIsQuickViewOpen] = useState(false);

  // Prefer memoized derived state so repeated renders are cheap
  const filteredProducts = useMemo(() => {
    let filtered = products;

    // Filter by store availability
    if (storeId) {
      filtered = filtered.filter(p => p.availableStores.includes(storeId));
    }

    // Filter by category
    if (selectedCategory !== 'all') {
      filtered = filtered.filter(p => p.category.toLowerCase() === selectedCategory);
    }

    // Filter by search query (name / description)
    const q = query.trim().toLowerCase();
    if (q) {
      filtered = filtered.filter(p => (p.name + ' ' + p.description).toLowerCase().includes(q));
    }

    return filtered;
  }, [selectedCategory, storeId, query]);

  const handleProductClick = useCallback((productId) => {
    const product = products.find(p => p.id === productId);
    if (product) {
      setSelectedProduct(product);
      setIsQuickViewOpen(true);
    }
  }, []);

  // Preload product images to ensure the page is ready in one shot
  const [preloading, setPreloading] = useState(true);

  useEffect(() => {
    let active = true;
    setPreloading(true);

    const preload = async () => {
      // Preload images for ALL products once, so filtering never needs to wait
      const urls = products.map(p => p.image);
      const loaders = urls.map(src => new Promise((resolve) => {
        const img = new Image();
        img.src = src;
        img.onload = () => resolve();
        img.onerror = () => resolve();
      }));

      // Timeout fallback so we don't block forever (3s is enough for "initial" feel)
      const timeout = new Promise((resolve) => setTimeout(resolve, 3000));
      await Promise.race([Promise.all(loaders), timeout]);

      if (active) setPreloading(false);
    };

    preload();

    return () => { active = false; };
  }, []); // Run only once on mount

  const handleBackClick = () => {
    if (window.REACT_APP_NAVIGATE) {
      window.REACT_APP_NAVIGATE('/');
    }
  };

  const handleChangeStore = () => {
    if (window.REACT_APP_NAVIGATE) {
      window.REACT_APP_NAVIGATE('/find-store');
    }
  };

  // Scroll to category section
  const scrollToCategory = useCallback((categoryId) => {
    setSelectedCategory(categoryId);
    // Allow the DOM to settle then smooth scroll so the selected state is visible
    setTimeout(() => {
      // Scroll just enough to likely trigger the sticky state, but not too far
      window.scrollTo({ top: 400, behavior: 'smooth' });
    }, 50);
  }, []);



  return (
    <div className="min-h-screen bg-gradient-to-br from-obsidian via-cocoa to-cocoa-dark">
      {/* Search: sticky with location selector - positioned directly under navbar */}
      <MenuStickySearch
        value={query}
        onChange={setQuery}
      />

      {/* Main Content - offset for sticky header (navbar + search bar) */}
      <div className="pt-48 pb-12">
        <div className="max-w-[1920px] mx-auto px-8">
          {/* Back Button */}
          <motion.button
            onClick={handleBackClick}
            className="mb-6 flex items-center gap-2 text-cream/70 hover:text-gold transition-colors cursor-pointer font-outfit whitespace-nowrap"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            whileHover={{ x: -5 }}
          >
            <i className="ri-arrow-left-line text-xl"></i>
            Back to Home
          </motion.button>

          {/* Category Header Section */}
          <motion.div
            className="mb-8 text-center"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
          >
            <h1 className="font-syncopate text-3xl md:text-4xl text-cream font-bold mb-2">
              {selectedCategory === 'all'
                ? 'Full Menu'
                : categories.find(c => c.id === selectedCategory)?.name || 'Menu'}
            </h1>
            <p className="font-outfit text-cream/60 text-sm md:text-base">
              Freshly baked delights and premium brews
            </p>
          </motion.div>

          {/* Products Grid - Dense 4 Column Masonry */}
          {preloading ? (
            <div className="w-full flex items-center justify-center py-36">
              <div className="text-cream/80 font-syncopate">Loading menu…</div>
            </div>
          ) : (
            <div className="w-full flex justify-center">
              <div
                className="flex flex-wrap gap-4 justify-start max-w-[1200px] w-full"
                data-product-shop
              >
                {filteredProducts.map((product, index) => (
                  <ProductCard
                    key={product.id}
                    product={product}
                    onClick={handleProductClick}
                    index={index}
                    variant="card"
                  />
                ))}
              </div>
            </div>
          )}

          {/* Empty State */}
          {filteredProducts.length === 0 && (
            <motion.div
              className="text-center py-20"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
            >
              <i className="ri-shopping-bag-line text-6xl text-gold/30 mb-4"></i>
              <h3 className="font-syncopate text-2xl text-cream mb-2">
                No Items Available
              </h3>
              <p className="font-outfit text-cream/60">
                Try selecting a different category or store
              </p>
            </motion.div>
          )}

          {/* Floating Menu FAB */}
          <MenuFab
            categories={categories}
            selectedCategory={selectedCategory}
            onSelect={scrollToCategory}
            position="right"
          />

          <AnimatePresence>
            {isQuickViewOpen && (
              <ProductQuickView
                product={selectedProduct}
                isOpen={isQuickViewOpen}
                onClose={() => setIsQuickViewOpen(false)}
              />
            )}
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
}
